def transform3(grid):
    H,W=len(grid),len(grid[0]); bg=grid[0][0]
    out=[row[:] for row in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==bg: continue
            for dr,dc in ((1,1),(1,-1)):
                rr,cc=r+dr,c+dc
                while 0<=rr<H and 0<=cc<W and grid[rr][cc]==bg:
                    out[rr][cc]=v; rr+=dr; cc+=dc
    return out
